func (e *ExecutableWrapper) Execute(inputLists [][]*BufferWrapper) ([][]*BufferWrapper, error) {
	return e.execute(inputLists, nil)
}

// ExecuteWithNonDonatableInputs runs the executable while preventing donation
// of the indexed inputs on every device. Indices are zero-based argument
// positions, not device IDs. The caller must not modify indices during the call.
func (e *ExecutableWrapper) ExecuteWithNonDonatableInputs(inputLists [][]*BufferWrapper, indices []int64) ([][]*BufferWrapper, error) {
	return e.execute(inputLists, indices)
}

func (e *ExecutableWrapper) execute(inputLists [][]*BufferWrapper, indices []int64) ([][]*BufferWrapper, error) {
	if e == nil || e.api == nil || e.executable == nil {
		return nil, fmt.Errorf("openxla: executable is closed")
	}
	if e.api.LoadedExecutable_Execute == 0 {
		return nil, fmt.Errorf("LoadedExecutable_Execute not available")
	}
	numDevices := len(inputLists)
	if numDevices == 0 {
		if len(indices) != 0 {
			return nil, fmt.Errorf("openxla: non-donatable indices require inputs")
		}
		return nil, nil
	}
	numArgs := len(inputLists[0])
	for _, index := range indices {
		if index < 0 || index >= int64(numArgs) {
			return nil, fmt.Errorf("openxla: non-donatable input index %d out of range", index)
		}
	}

	for d := 0; d < numDevices; d++ {
		if len(inputLists[d]) != numArgs {
			return nil, fmt.Errorf("openxla: ragged input lists: device 0 has %d args, device %d has %d args", numArgs, d, len(inputLists[d]))
		}
		for a := 0; a < numArgs; a++ {
			if inputLists[d][a] == nil || inputLists[d][a].buffer == nil {
				return nil, fmt.Errorf("openxla: nil buffer at device %d, arg %d", d, a)
			}
		}
	}

	numOutputs, err := e.NumOutputs()
	if err != nil {
		return nil, fmt.Errorf("openxla: determine num outputs: %w", err)
	}

	maxElements := int(^uint(0)>>1) / int(unsafe.Sizeof(uintptr(0)))
	if numArgs > maxElements/numDevices || numOutputs > maxElements/numDevices {
		return nil, fmt.Errorf("openxla: execution buffer lists overflow int")
	}

	rawArgs := make([]*Buffer, numDevices*numArgs)
	for d := 0; d < numDevices; d++ {
		for a := 0; a < numArgs; a++ {
			rawArgs[d*numArgs+a] = inputLists[d][a].buffer
		}
	}
	argPtrs := make([]**Buffer, numDevices)
	for d := 0; d < numDevices; d++ {
		if numArgs > 0 {
			argPtrs[d] = &rawArgs[d*numArgs]
		}
	}

	rawOutputs := make([]*Buffer, numDevices*numOutputs)
	outPtrs := make([]**Buffer, numDevices)
	for d := 0; d < numDevices; d++ {
		if numOutputs > 0 {
			outPtrs[d] = &rawOutputs[d*numOutputs]
		}
	}

	events := make([]*Event, numDevices)

	var opts ExecuteOptions
	opts.Struct_size = PJRT_ExecuteOptions_STRUCT_SIZE
	var pin runtime.Pinner
	defer pin.Unpin()
	if len(indices) != 0 {
		protected := append([]int64(nil), indices...)
		pin.Pin(&protected[0])
		opts.Non_donatable_input_indices = &protected[0]
		opts.Num_non_donatable_input_indices = uintptr(len(protected))
	}

	var args LoadedExecutable_Execute_Args
	args.Struct_size = PJRT_LoadedExecutable_Execute_Args_STRUCT_SIZE
	args.Executable = e.executable
	args.Options = &opts
	args.Num_devices = uintptr(numDevices)
	args.Num_args = uintptr(numArgs)
	if numDevices > 0 && numArgs > 0 {
		args.Argument_lists = unsafe.Pointer(&argPtrs[0])
	}
	if numDevices > 0 && numOutputs > 0 {
		args.Output_lists = unsafe.Pointer(&outPtrs[0])
	}
	if numDevices > 0 {
		args.Device_complete_events = unsafe.Pointer(&events[0])
	}

	if numDevices > 0 {
		if e.api.Event_Await == 0 || e.api.Event_Destroy == 0 {
			return nil, fmt.Errorf("openxla: required Event_Await or Event_Destroy not available")
		}
	}
	if numOutputs > 0 && e.api.Buffer_Destroy == 0 {
		return nil, fmt.Errorf("openxla: Buffer_Destroy not available")
	}

	// Await every device before releasing outputs, even if an earlier device
	// reports failure. Event destruction failures are returned to the caller.
	runErr := decodeError(e.api, callPJRT(e.api.LoadedExecutable_Execute, uintptr(unsafe.Pointer(&args))))
	for _, ev := range events {
		runErr = errors.Join(runErr, awaitEvent(e.api, ev))
	}
	if runErr != nil {
		for _, buf := range rawOutputs {
			wrapper := &BufferWrapper{api: e.api, buffer: buf}
			runErr = errors.Join(runErr, wrapper.Destroy())
		}
		return nil, runErr
	}

	results := make([][]*BufferWrapper, numDevices)
	for d := 0; d < numDevices; d++ {
		results[d] = make([]*BufferWrapper, numOutputs)
		for o := 0; o < numOutputs; o++ {
			results[d][o] = &BufferWrapper{
				api:    e.api,
				buffer: rawOutputs[d*numOutputs+o],
			}
		}
	}

	return results, nil
}

// Destroy destroys the loaded executable on device.
func (e *ExecutableWrapper) Destroy() error {
	if e.executable == nil || e.api.LoadedExecutable_Destroy == 0 {
		return nil
	}
	var args LoadedExecutable_Destroy_Args
	args.Struct_size = PJRT_LoadedExecutable_Destroy_Args_STRUCT_SIZE
	args.Executable = e.executable
	errPtr := callPJRT(e.api.LoadedExecutable_Destroy, uintptr(unsafe.Pointer(&args)))
	e.executable = nil
	if errPtr != nil {
		return decodeError(e.api, errPtr)
	}
	return nil
}

// BufferWrapper wraps an on-device PJRT Buffer.
type BufferWrapper struct {
	api    *Api
	buffer *Buffer
}

// IsOnCPU reports whether PJRT stores this buffer on the CPU. It does not
// establish that its address may be exposed to Go.
func (b *BufferWrapper) IsOnCPU() (bool, error) {
	if b == nil || b.buffer == nil {
		return false, fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_IsOnCpu == 0 {
		return false, fmt.Errorf("openxla: Buffer_IsOnCpu not available")
	}
	args := Buffer_IsOnCpu_Args{Struct_size: PJRT_Buffer_IsOnCpu_Args_STRUCT_SIZE, Buffer: b.buffer}
	if err := decodeError(b.api, callPJRT(b.api.Buffer_IsOnCpu, uintptr(unsafe.Pointer(&args)))); err != nil {
		return false, err
	}
	return args.Is_on_cpu, nil
}

// IncreaseExternalReferenceCount prevents PJRT from moving or deleting the
// buffer's storage until the matching DecreaseExternalReferenceCount call.
// The buffer and client must remain open, and callers must serialize reference
// operations with each other and with Destroy. This does not wait for readiness.
func (b *BufferWrapper) IncreaseExternalReferenceCount() error {
	if b == nil || b.buffer == nil {
		return fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_IncreaseExternalReferenceCount == 0 || b.api.Buffer_DecreaseExternalReferenceCount == 0 {
		return fmt.Errorf("openxla: external buffer references not available")
	}
	args := Buffer_IncreaseExternalReferenceCount_Args{Struct_size: PJRT_Buffer_IncreaseExternalReferenceCount_Args_STRUCT_SIZE, Buffer: b.buffer}
	return decodeError(b.api, callPJRT(b.api.Buffer_IncreaseExternalReferenceCount, uintptr(unsafe.Pointer(&args))))
}

// DecreaseExternalReferenceCount releases one reference previously acquired by
// IncreaseExternalReferenceCount. The buffer must remain open until this returns.
func (b *BufferWrapper) DecreaseExternalReferenceCount() error {
	if b == nil || b.buffer == nil {
		return fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_DecreaseExternalReferenceCount == 0 {
		return fmt.Errorf("openxla: external buffer references not available")
	}
	args := Buffer_DecreaseExternalReferenceCount_Args{Struct_size: PJRT_Buffer_DecreaseExternalReferenceCount_Args_STRUCT_SIZE, Buffer: b.buffer}
	return decodeError(b.api, callPJRT(b.api.Buffer_DecreaseExternalReferenceCount, uintptr(unsafe.Pointer(&args))))
}

// OpaqueDeviceMemoryDataPointer returns a plugin-specific device memory pointer.
// The caller must hold a positive external reference count for the entire use
// of the pointer. This method does not establish CPU accessibility, readiness,
// element layout, or permission to mutate memory. A nil pointer may describe
// an empty allocation; the caller must check its expected storage size.
func (b *BufferWrapper) OpaqueDeviceMemoryDataPointer() (unsafe.Pointer, error) {
	if b == nil || b.buffer == nil {
		return nil, fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_OpaqueDeviceMemoryDataPointer == 0 {
		return nil, fmt.Errorf("openxla: device memory pointer not available")
	}
	args := Buffer_OpaqueDeviceMemoryDataPointer_Args{Struct_size: PJRT_Buffer_OpaqueDeviceMemoryDataPointer_Args_STRUCT_SIZE, Buffer: b.buffer}
	if err := decodeError(b.api, callPJRT(b.api.Buffer_OpaqueDeviceMemoryDataPointer, uintptr(unsafe.Pointer(&args)))); err != nil {
		return nil, err
	}
	return args.Device_memory_ptr, nil
}

// OnDeviceSizeInBytes reports the size of this buffer's device storage.
func (b *BufferWrapper) OnDeviceSizeInBytes() (uint64, error) {
	if b == nil || b.buffer == nil {
		return 0, fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_OnDeviceSizeInBytes == 0 {
		return 0, fmt.Errorf("openxla: device buffer size not available")
	}
	args := Buffer_OnDeviceSizeInBytes_Args{Struct_size: PJRT_Buffer_OnDeviceSizeInBytes_Args_STRUCT_SIZE, Buffer: b.buffer}
	if err := decodeError(b.api, callPJRT(b.api.Buffer_OnDeviceSizeInBytes, uintptr(unsafe.Pointer(&args)))); err != nil {
		return 0, err
	}
	return uint64(args.On_device_size_in_bytes), nil
}

// IsDenseRowMajor reports whether the buffer has an untiled, dense row-major
// layout. Other layout representations return false. This query uses the
// legacy PJRT layout API and does not establish CPU accessibility or readiness.
func (b *BufferWrapper) IsDenseRowMajor() (bool, error) {
	if b == nil || b.buffer == nil {
		return false, fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_GetMemoryLayout == 0 {
		return false, fmt.Errorf("openxla: buffer memory layout not available")
	}
	_, dims, err := b.Shape()
	if err != nil {
		return false, err
	}
	args := Buffer_GetMemoryLayout_Args{Struct_size: PJRT_Buffer_GetMemoryLayout_Args_STRUCT_SIZE, Buffer: b.buffer}
	if err := decodeError(b.api, callPJRT(b.api.Buffer_GetMemoryLayout, uintptr(unsafe.Pointer(&args)))); err != nil {
		return false, err
	}
	layout := args.Layout
	// Legacy XLA fills this embedded output by value without initializing
	// its struct_size fields. The enclosing call's ABI fixes its storage size;
	// bound the referenced axis data by the independently queried shape rank.
	if layout.Type != Buffer_MemoryLayout_Type_Tiled {
		return false, nil
	}
	tiled := layout.Union_pad
	if tiled.Num_tiles != 0 {
		return false, nil
	}
	if tiled.Minor_to_major_size != uintptr(len(dims)) {
		return false, fmt.Errorf("openxla: buffer layout rank mismatch")
	}
	if len(dims) != 0 && tiled.Minor_to_major == nil {
		return false, fmt.Errorf("openxla: buffer layout axes missing")
	}
	for i, axis := range unsafe.Slice(tiled.Minor_to_major, len(dims)) {
		if axis != int64(len(dims)-1-i) {
			return false, nil
		}
	}
	return true, nil
}

// WaitReady waits for this buffer's producer to finish.
func (b *BufferWrapper) WaitReady() error {
	if b == nil || b.buffer == nil {
		return fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_ReadyEvent == 0 {
		return fmt.Errorf("openxla: Buffer_ReadyEvent not available")
	}
	if b.api.Event_Await == 0 || b.api.Event_Destroy == 0 {
		return fmt.Errorf("openxla: required Event_Await or Event_Destroy not available")
	}
	args := Buffer_ReadyEvent_Args{Struct_size: PJRT_Buffer_ReadyEvent_Args_STRUCT_SIZE, Buffer: b.buffer}
	if err := decodeError(b.api, callPJRT(b.api.Buffer_ReadyEvent, uintptr(unsafe.Pointer(&args)))); err != nil {
		return err
	}
	if args.Event == nil {
		return fmt.Errorf("openxla: Buffer_ReadyEvent returned nil event")
	}
	return awaitEvent(b.api, args.Event)
}

// Device returns the device on which the buffer resides.
func (b *BufferWrapper) Device() (*Device, error) {
	if b == nil || b.buffer == nil {
		return nil, fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_Device == 0 {
		return nil, fmt.Errorf("openxla: buffer device query not available")
	}
	args := Buffer_Device_Args{Struct_size: PJRT_Buffer_Device_Args_STRUCT_SIZE, Buffer: b.buffer}
	if err := decodeError(b.api, callPJRT(b.api.Buffer_Device, uintptr(unsafe.Pointer(&args)))); err != nil {
		return nil, err
	}
	if args.Device == nil {
		return nil, fmt.Errorf("openxla: buffer has no device")
	}
	return args.Device, nil
}

// Shape returns the buffer's element type and a copy of its dimensions.
func (b *BufferWrapper) Shape() (Buffer_Type, []int64, error) {
	if b == nil || b.buffer == nil {
		return Buffer_Type_INVALID, nil, fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_ElementType == 0 || b.api.Buffer_Dimensions == 0 {
		return Buffer_Type_INVALID, nil, fmt.Errorf("openxla: buffer shape queries not available")
	}
	var typeArgs Buffer_ElementType_Args
	typeArgs.Struct_size = PJRT_Buffer_ElementType_Args_STRUCT_SIZE
	typeArgs.Buffer = b.buffer
	if errPtr := callPJRT(b.api.Buffer_ElementType, uintptr(unsafe.Pointer(&typeArgs))); errPtr != nil {
		return Buffer_Type_INVALID, nil, decodeError(b.api, errPtr)
	}
	var dimsArgs Buffer_Dimensions_Args
	dimsArgs.Struct_size = PJRT_Buffer_Dimensions_Args_STRUCT_SIZE
	dimsArgs.Buffer = b.buffer
	if errPtr := callPJRT(b.api.Buffer_Dimensions, uintptr(unsafe.Pointer(&dimsArgs))); errPtr != nil {
		return Buffer_Type_INVALID, nil, decodeError(b.api, errPtr)
	}
	if dimsArgs.Num_dims > uintptr(int(^uint(0)>>1))/unsafe.Sizeof(int64(0)) || (dimsArgs.Num_dims != 0 && dimsArgs.Dims == nil) {
		return Buffer_Type_INVALID, nil, fmt.Errorf("openxla: invalid buffer dimensions")
	}
	dims := append([]int64(nil), unsafe.Slice(dimsArgs.Dims, int(dimsArgs.Num_dims))...)
	return typeArgs.Type, dims, nil
}

// ToHost copies on-device buffer data to host memory synchronously.
// The caller must not access dst until the call returns. Go allocations are
// pinned until the completion event has been awaited and destroyed.
func (b *BufferWrapper) ToHost(dst unsafe.Pointer, dstSize uintptr) error {
	if b == nil || b.buffer == nil {
		return fmt.Errorf("openxla: buffer is closed")
	}
	if b.api.Buffer_ToHostBuffer == 0 {
		return fmt.Errorf("Buffer_ToHostBuffer not available")
	}
	if b.api.Event_Await == 0 || b.api.Event_Destroy == 0 {
		return fmt.Errorf("openxla: required Event_Await or Event_Destroy not available")
	}
	var pin runtime.Pinner
	defer pin.Unpin()
	if dst != nil {
		pin.Pin(dst)
	}
	var args Buffer_ToHostBuffer_Args
	args.Struct_size = PJRT_Buffer_ToHostBuffer_Args_STRUCT_SIZE
	args.Src = b.buffer
	args.Dst = dst
	args.Dst_size = dstSize
	if errPtr := callPJRT(b.api.Buffer_ToHostBuffer, uintptr(unsafe.Pointer(&args))); errPtr != nil {
		return decodeError(b.api, errPtr)
	}
	return awaitEvent(b.api, args.Event)
}

// Destroy destroys the on-device buffer.
func (b *BufferWrapper) Destroy() error {
	if b.buffer == nil || b.api.Buffer_Destroy == 0 {
		return nil
	}
	var args Buffer_Destroy_Args
	args.Struct_size = PJRT_Buffer_Destroy_Args_STRUCT_SIZE
	args.Buffer = b.buffer
	errPtr := callPJRT(b.api.Buffer_Destroy, uintptr(unsafe.Pointer(&args)))
	b.buffer = nil
	if errPtr != nil {
		return decodeError(b.api, errPtr)
	}
	return nil
}

// Destroy frees the client and shuts down connections.
func (c *ClientWrapper) Destroy() error {
	if c.client == nil || c.api.Client_Destroy == 0 {
		return nil
	}
	var args Client_Destroy_Args
	args.Struct_size = PJRT_Client_Destroy_Args_STRUCT_SIZE
	args.Client = c.client
	errPtr := callPJRT(c.api.Client_Destroy, uintptr(unsafe.Pointer(&args)))
	c.client = nil
	if errPtr != nil {
		return decodeError(c.api, errPtr)
	}
	return nil
}

// awaitEvent consumes an event, preserving both completion and release errors.
func awaitEvent(api *Api, event *Event) (err error) {
	if event == nil {
		return nil
	}
	defer func() {
		args := Event_Destroy_Args{Struct_size: PJRT_Event_Destroy_Args_STRUCT_SIZE, Event: event}
		err = errors.Join(err, decodeError(api, callPJRT(api.Event_Destroy, uintptr(unsafe.Pointer(&args)))))
	}()
	args := Event_Await_Args{Struct_size: PJRT_Event_Await_Args_STRUCT_SIZE, Event: event}
	return decodeError(api, callPJRT(api.Event_Await, uintptr(unsafe.Pointer(&args))))
}

func decodeError(api *Api, errPtr *ErrorHandle) error {
	if errPtr == nil {
		return nil
	}
	defer func() {
		if api.Error_Destroy != 0 {
			var dArgs Error_Destroy_Args
			dArgs.Struct_size = PJRT_Error_Destroy_Args_STRUCT_SIZE
			dArgs.Error = errPtr
			callPJRTProc(api.Error_Destroy, uintptr(unsafe.Pointer(&dArgs)))
		}
	}()

	if api.Error_Message != 0 {
		var mArgs Error_Message_Args
		mArgs.Struct_size = PJRT_Error_Message_Args_STRUCT_SIZE
		mArgs.Error = errPtr
		callPJRTProc(api.Error_Message, uintptr(unsafe.Pointer(&mArgs)))
		if mArgs.Message != nil {
			msgBytes := unsafe.Slice(mArgs.Message, mArgs.Message_size)
			return fmt.Errorf("openxla error: %s", string(msgBytes))
		}
	}
	return fmt.Errorf("openxla error (unknown)")
}
